/**
 * Full-node stack generator.
 *
 * Produces a Docker Compose stack that runs, on the same device:
 *   - Bitcoin Core (full or pruned node)
 *   - LND, chain-synced through that bitcoind (ZMQ + RPC)
 *   - optionally Alby Hub, which exposes the LND node over
 *     Nostr Wallet Connect (NWC)
 *
 * The generated files contain a freshly generated RPC password, so they
 * are written with restrictive permissions and are git-ignored.
 */
import { createHmac, randomBytes } from "node:crypto";

export type FullNodeNetwork = "mainnet" | "testnet4" | "signet";

export interface FullNodeOptions {
  network: FullNodeNetwork;
  /** Prune target in MB; 0 = archival (full) node. Min 550 when set. */
  pruneMb: number;
  /** Include Alby Hub to get an NWC connection string for this node. */
  withAlbyHub: boolean;
  /** LND node alias (public). */
  alias: string;
}

export interface GeneratedFile {
  /** Path relative to the fullnode/ directory. */
  relPath: string;
  content: string;
  /** Unix file mode; configs with secrets get 0o600. */
  mode?: number;
}

export interface FullNodeStack {
  files: GeneratedFile[];
  commands: string[];
  notes: string[];
}

export const BITCOIND_IMAGE = "bitcoin/bitcoin:31";
export const LND_IMAGE = "lightninglabs/lnd:v0.20.1-beta";
export const ALBYHUB_IMAGE = "ghcr.io/getalby/hub:latest";

const RPC_USER = "btcmcp";

/** bitcoin.conf chain identifier and LND macaroon directory per network. */
const CHAIN: Record<FullNodeNetwork, { chain: string; lndFlag: string }> = {
  mainnet: { chain: "main", lndFlag: "bitcoin.mainnet=true" },
  testnet4: { chain: "testnet4", lndFlag: "bitcoin.testnet4=true" },
  signet: { chain: "signet", lndFlag: "bitcoin.signet=true" },
};

/**
 * Bitcoin Core rpcauth line: user:salt$hmac_sha256(salt, password)
 * (same algorithm as Core's share/rpcauth/rpcauth.py).
 */
export function rpcAuthLine(user: string, password: string, salt?: string): string {
  const s = salt ?? randomBytes(16).toString("hex");
  const hash = createHmac("sha256", s).update(password).digest("hex");
  return `rpcauth=${user}:${s}$${hash}`;
}

export function sanitizeFullNodeOptions(raw: unknown): FullNodeOptions {
  const o = raw as Partial<FullNodeOptions>;
  const network: FullNodeNetwork =
    o.network === "testnet4" || o.network === "signet" ? o.network : "mainnet";
  let pruneMb = Number(o.pruneMb);
  if (!Number.isFinite(pruneMb) || pruneMb < 0) pruneMb = 0;
  if (pruneMb > 0 && pruneMb < 550) pruneMb = 550; // bitcoind minimum
  const alias = String(o.alias ?? "btc-mcp-srv node")
    .replace(/[^\x20-\x7e]/g, "")
    .slice(0, 32) || "btc-mcp-srv node";
  return {
    network,
    pruneMb: Math.floor(pruneMb),
    withAlbyHub: o.withAlbyHub !== false,
    alias,
  };
}

function bitcoinConf(opts: FullNodeOptions, rpcPassword: string): string {
  const { chain } = CHAIN[opts.network];
  const storage =
    opts.pruneMb > 0
      ? [`# Pruned node: keeps ~${opts.pruneMb} MB of blocks`, `prune=${opts.pruneMb}`]
      : [
          "# Archival node (mainnet needs ~750+ GB and growing).",
          "# Set prune=<MB> instead if disk space is limited.",
          "txindex=1",
        ];
  return [
    "# Generated by btc-mcp-srv setup — Bitcoin Core configuration",
    "# Docs: https://github.com/bitcoin/bitcoin/blob/master/doc/bitcoin-conf.md",
    "",
    `chain=${chain}`,
    "server=1",
    "daemon=0",
    ...storage,
    "",
    "# ZMQ notifications consumed by LND",
    "zmqpubrawblock=tcp://0.0.0.0:28332",
    "zmqpubrawtx=tcp://0.0.0.0:28333",
    "",
    "# RPC auth (password lives in lnd.conf; this line stores a salted hash)",
    rpcAuthLine(RPC_USER, rpcPassword),
    "",
    `[${chain}]`,
    "# Uniform ports across networks to keep the stack simple",
    "port=8333",
    "rpcport=8332",
    "rpcbind=0.0.0.0",
    "# RPC reachable from localhost and private/docker ranges only;",
    "# the compose file additionally publishes RPC on 127.0.0.1.",
    "rpcallowip=127.0.0.1",
    "rpcallowip=10.0.0.0/8",
    "rpcallowip=172.16.0.0/12",
    "rpcallowip=192.168.0.0/16",
    "",
  ].join("\n");
}

function lndConf(opts: FullNodeOptions, rpcPassword: string): string {
  return [
    "# Generated by btc-mcp-srv setup — LND configuration",
    "",
    "[Application Options]",
    `alias=${opts.alias}`,
    "listen=0.0.0.0:9735",
    "restlisten=0.0.0.0:8080",
    "rpclisten=0.0.0.0:10009",
    "# Make the TLS cert valid for in-compose and host access",
    "tlsextradomain=lnd",
    "tlsextraip=127.0.0.1",
    "",
    "[Bitcoin]",
    CHAIN[opts.network].lndFlag,
    "bitcoin.node=bitcoind",
    "",
    "[Bitcoind]",
    "bitcoind.rpchost=bitcoind:8332",
    `bitcoind.rpcuser=${RPC_USER}`,
    `bitcoind.rpcpass=${rpcPassword}`,
    "bitcoind.zmqpubrawblock=tcp://bitcoind:28332",
    "bitcoind.zmqpubrawtx=tcp://bitcoind:28333",
    "",
  ].join("\n");
}

function dockerCompose(opts: FullNodeOptions): string {
  const macaroonPath = `/lnd/data/chain/bitcoin/${opts.network}/admin.macaroon`;
  const lines = [
    "# Generated by btc-mcp-srv setup — full-node stack",
    "# Start:  docker compose up -d      Stop:  docker compose down",
    "",
    "services:",
    "  bitcoind:",
    `    image: ${BITCOIND_IMAGE}`,
    "    restart: unless-stopped",
    "    stop_grace_period: 10m",
    "    volumes:",
    "      - ./bitcoin:/home/bitcoin/.bitcoin",
    "    ports:",
    '      - "127.0.0.1:8332:8332"   # RPC (localhost only)',
    '      - "8333:8333"             # P2P',
    "",
    "  lnd:",
    `    image: ${LND_IMAGE}`,
    "    restart: unless-stopped",
    "    depends_on:",
    "      - bitcoind",
    "    volumes:",
    "      - ./lnd:/root/.lnd",
    "    ports:",
    '      - "127.0.0.1:8080:8080"   # REST (localhost only)',
    '      - "127.0.0.1:10009:10009" # gRPC (localhost only)',
    '      - "9735:9735"             # Lightning P2P',
  ];
  if (opts.withAlbyHub) {
    lines.push(
      "",
      "  albyhub:",
      `    image: ${ALBYHUB_IMAGE}`,
      "    restart: unless-stopped",
      "    depends_on:",
      "      - lnd",
      "    environment:",
      "      - WORK_DIR=/data",
      "      - LN_BACKEND_TYPE=LND",
      "      - LND_ADDRESS=lnd:10009",
      "      - LND_CERT_FILE=/lnd/tls.cert",
      `      - LND_MACAROON_FILE=${macaroonPath}`,
      "    volumes:",
      "      - ./albyhub:/data",
      "      - ./lnd:/lnd:ro",
      "    ports:",
      '      - "127.0.0.1:8029:8080"   # Alby Hub web UI (localhost only)',
    );
  }
  lines.push("");
  return lines.join("\n");
}

export function generateFullNodeStack(
  raw: unknown,
  rpcPassword = randomBytes(20).toString("hex"),
): FullNodeStack {
  const opts = sanitizeFullNodeOptions(raw);
  const netFlag = opts.network === "mainnet" ? "" : ` --network=${opts.network}`;

  const files: GeneratedFile[] = [
    { relPath: "docker-compose.yml", content: dockerCompose(opts) },
    { relPath: "bitcoin/bitcoin.conf", content: bitcoinConf(opts, rpcPassword), mode: 0o600 },
    { relPath: "lnd/lnd.conf", content: lndConf(opts, rpcPassword), mode: 0o600 },
    {
      relPath: "stack.json",
      content: JSON.stringify(
        {
          network: opts.network,
          withAlbyHub: opts.withAlbyHub,
          generatedAt: new Date().toISOString(),
        },
        null,
        2,
      ),
    },
  ];

  const commands = [
    "cd fullnode",
    "docker compose up -d",
    `docker compose exec lnd lncli${netFlag} create   # create the LND wallet (first run only)`,
    `docker compose exec lnd lncli${netFlag} getinfo  # check sync status`,
  ];

  const notes = [
    opts.pruneMb > 0
      ? `Pruned node (~${opts.pruneMb} MB of blocks). Initial sync still downloads the whole chain.`
      : "Archival node — mainnet currently needs ~750+ GB of disk.",
    "After a restart, unlock the wallet with: docker compose exec lnd lncli" +
      `${netFlag} unlock`,
    opts.withAlbyHub
      ? "Alby Hub (NWC): open http://localhost:8029 after LND is synced, finish its onboarding, then create a connection to get your nostr+walletconnect:// string and paste it in this setup GUI (NWC backend)."
      : "To use this node with btc-mcp-srv, pick the LND backend: REST URL https://127.0.0.1:8080, TLS cert fullnode/lnd/tls.cert, macaroon fullnode/lnd/data/chain/bitcoin/" +
        `${opts.network}/admin.macaroon (hex-encode it, e.g. node -e "console.log(require('fs').readFileSync('fullnode/lnd/data/chain/bitcoin/${opts.network}/admin.macaroon').toString('hex'))").`,
    "LND needs bitcoind to be fully synced before it becomes operational.",
  ];

  return { files, commands, notes };
}
